namespace Acme.Ticketing.Application.Framework;

public enum ErrorKind
{
    NotFound,
    Invalid,
    Conflict,
    Forbidden,
}

/// <param name="Errors">Validation messages by property path (camelCase).</param>
public sealed record Error(ErrorKind Kind, string Message, IReadOnlyDictionary<string, string[]>? Errors = null)
{
    public static Error NotFound(string message = "Not found.") => new(ErrorKind.NotFound, message);
    public static Error Conflict(string message) => new(ErrorKind.Conflict, message);
    public static Error Forbidden(string message = "Forbidden.") => new(ErrorKind.Forbidden, message);
    public static Error Invalid(string path, string message) =>
        new(ErrorKind.Invalid, message, new Dictionary<string, string[]> { [path] = [message] });
}

public class Result
{
    protected Result(Error? error) => Error = error;

    public Error? Error { get; }
    public bool IsSuccess => Error is null;

    public static Result Success { get; } = new(null);
    public static implicit operator Result(Error error) => new(error);
}

public sealed class Result<T> : Result
{
    private readonly T? _value;

    private Result(T? value, Error? error) : base(error) => _value = value;

    public T Value => IsSuccess ? _value! : throw new InvalidOperationException("The result is an error.");

    public static implicit operator Result<T>(T value) => new(value, null);
    public static implicit operator Result<T>(Error error) => new(default, error);
}
