{
    options.FallbackPolicy = new Microsoft.AspNetCore.Authorization.AuthorizationPolicyBuilder()
        .RequireAuthenticatedUser().Build();
    foreach (var right in Rights.Known)
        options.AddPolicy(right, policy => policy.RequireAssertion(context =>
            context.User.Claims.Any(c => c.Type == "right" && (c.Value == right || c.Value == Rights.All))));
});

