            ValidAlgorithms = [SecurityAlgorithms.HmacSha256],
            ValidateIssuerSigningKey = true,
            RequireSignedTokens = true,
            ValidateIssuer = false,
            ValidateAudience = false,
            ValidateLifetime = true,
            RequireExpirationTime = true,
            ClockSkew = TimeSpan.Zero,
        };
    });

builder.Services.AddAuthorization(options =>
{
    options.FallbackPolicy = new Microsoft.AspNetCore.Authorization.AuthorizationPolicyBuilder()
        .RequireAuthenticatedUser().Build();
    foreach (var right in Rights.Known)
        options.AddPolicy(right, policy => policy.RequireAssertion(context =>
            context.User.Claims.Any(c => c.Type == "right" && (c.Value == right || c.Value == Rights.All))));
});

var app = builder.Build();
app.Services.EnsureTicketingDatabase();

app.UseAuthentication();
app.UseAuthorization();
app.MapTicketingEndpoints();
app.Run();

static byte[] SigningKey(string? key)
{
    var bytes = Encoding.UTF8.GetBytes(key ?? throw new InvalidOperationException("Jwt:Key is not configured."));
    if (bytes.Length >= 32)
        return bytes;
    var padded = new byte[32];
    Array.Fill(padded, (byte)' ');
    bytes.CopyTo(padded, 0);
    return padded;
}

